/* @autogenerated */
import { Component, inject } from '@angular/core';
import { ThemeAsset } from 'app/features/template/theme-asset/model/theme-asset.model';
import { ThemeAssetRepository } from 'app/features/template/theme-asset/repository/theme-asset-repository.service';
import { ConfirmSelectionAction } from 'app/shared/toolkit/action/confirm-selection-action';

@Component({ selector: 'theme-asset-view-disable-selection-action', standalone: false, template: '' })
export class ThemeAssetViewDisableSelectionActionComponent extends ConfirmSelectionAction<ThemeAsset> {
  readonly name = 'disableSelection';
  protected readonly scope = 'template/theme-asset';
  protected readonly repository = inject(ThemeAssetRepository);

  protected override appliesTo(items: ThemeAsset[]) {
    return items.every((item) => item.enabled !== false);
  }

  protected runSelection(items: ThemeAsset[]) {
    return this.repository.disableSelection({ uids: items.map((item) => item.uid) });
  }
}
